class JsonOutputGenerator:
    def generate(self, data):
        return json.dumps(data)

class HtmlOutputGenerator:
    def generate(self, data):
        return f"Sum of the areas of provided shapes: {data['sum']}"

class SumOutputter:
    def __init__(self, areaCalculator: AreaCalculator) -> None:
        self.calculator = areaCalculator

    def format_json(self):
        data = {
            'sum': self.calculator.sum()
        }
        return JsonOutputGenerator().generate(data)

    def format_html(self):
        return HtmlOutputGenerator().generate({'sum': self.calculator.sum()})
